        it('decrypts badly signed hash', async () => {
            // @ts-ignore
            decryptSigned.mockReset();
            // @ts-ignore
            decryptSigned.mockImplementation(({ armoredMessage }) =>
                Promise.resolve({ data: `dec:${armoredMessage}`, verified: 2 })
