                const timeout = setTimeout(() => linkFetchErrors.current.delete(cacheKey), FAILING_FETCH_BACKOFF_MS);
                linkFetchErrors.current.set(cacheKey, { error: err, timeout });
            }
            throw err;
        }
    };

    return useLinkInner(
        fetchLink,
        linksKeys,
        linksState,
        getVerificationKey,
        getSharePrivateKey,
        CryptoProxy.importPrivateKey
    );
}

